import{_ as i,C as r,o as s,c as l,a2 as t,j as o,a,E as d}from"./chunks/framework.Dx-TCpNt.js";const b=JSON.parse('{"title":"KomaYomi — a local-first manga panel reader","titleTemplate":false,"description":"KomaYomi (Koma = manga panel, Yomi = reading) documentation — a local-first manga panel reader for language study: compare Japanese, Chinese and English pages, detect panels, align artwork and take notes.","frontmatter":{"layout":"home","titleTemplate":false,"description":"KomaYomi (Koma = manga panel, Yomi = reading) documentation — a local-first manga panel reader for language study: compare Japanese, Chinese and English pages, detect panels, align artwork and take notes.","title":"KomaYomi — a local-first manga panel reader","hero":{"name":"KomaYomi","text":"Manga Panel Reader","tagline":"日本語はすべて漫画から学んだ~","image":{"src":"/assets/screenshots/hero-real-library.png","alt":"Compare reader with three language panes from a real library; the manga artwork is blurred"},"actions":[{"theme":"brand","text":"Get started","link":"/guide/introduction"},{"theme":"alt","text":"Data formats","link":"/data-format"}]},"features":[{"title":"Panels first","details":"Automatic XY-cut detection with manual drawing, merging, numbering and reusable layout templates. Notes and marks follow the artwork when panels are re-detected or a template is applied, so a re-layout no longer loses work."},{"title":"Compare multiple languages","details":"Side-by-side or overlay views, per-language masks, wheel zoom and pan, plus page / panel / anchor / grid alignment with reusable presets."},{"title":"Notes that travel","details":"Markdown notes at page or panel scope, tags, sources, a scratch pad, full-text search and one-click \\"copy context\\" for pasting into an LLM."},{"title":"Portable output","details":"Export HTML with an image folder or as a single embedded file, render page / panel / collage PNGs, and move everything as a `.mnproj` project."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1794830541000}'),m={name:"index.md"};function p(g,e,h,c,u,f){const n=r("Badge");return s(),l("div",null,[e[4]||(e[4]=t('<h2 id="what-is-komayomi" tabindex="-1">What is KomaYomi? <a class="header-anchor" href="#what-is-komayomi" aria-label="Permalink to &quot;What is KomaYomi?&quot;">​</a></h2><p>KomaYomi — <strong>Koma</strong> (コマ, manga panel) + <strong>Yomi</strong> (読み, reading) — is a <strong>local web application</strong> for learning languages with manga: read the same pages in Japanese, Chinese and English, align them precisely, and take notes. Its unit of work is the panel, not the page: structure the page first, then align editions, then anchor notes to the artwork. Your page images stay in a <code>raw/</code> folder; every panel, note, tag, alignment offset and annotation lives in plain JSON under <code>data/</code>. Nothing leaves the machine unless you export it.</p><p>It is designed for study and translation review rather than for hosting copyrighted material: bring your own scans, point the app at the folder, and work page by page.</p><h2 id="status-at-a-glance" tabindex="-1">Status at a glance <a class="header-anchor" href="#status-at-a-glance" aria-label="Permalink to &quot;Status at a glance&quot;">​</a></h2><p>KomaYomi is at <strong>1.0.1</strong>. The documentation distinguishes what exists today from what is planned.</p><div class="status-list"><div><strong>Working today</strong> — library scanning including multi-work roots, XY-cut panel detection, manual panel editing, splitting a panel and reordering the numbering with quick 1–10 positions and right-click move-to, panel grouping and page history, three sidebar page-list layouts (two-column thumbnails, single-column thumbnails, and a list with languages and note counts), panel/layout templates, vector annotations with anchor leaders, compare reader with masks and four alignment modes, a third original-page view with per-language zoom and pan plus a linked/independent switch, panel detail views with per-panel deep links (double-click any compare row, including its margins, to open one), per-language session-only alignment in the detail view, previous/next panel across page and chapter boundaries, focus mode, edit and read-only modes, Markdown notes with search and single-editor editing, typed notes (Background, Vocabulary and Reaction at page or panel scope, one type per enabled language, custom types stored in `data/library.json`, with filtering, grouping and add-by-type), a start screen with six first-run steps and import / new-library / open-project / guide entries, HTML / PNG / PDF (print) / Word export with annotations baked by default, backup ZIP plus scheduled automatic backups, cache management, upload to a WebDAV/network target, a WebDAV/network image source with on-demand LRU caching and an offline write queue, atomic page saves with schema validation, `.bak` rotation and a concurrent-write lock, `.mnproj` project export/import, CLI batch tools.</div><div><strong>Planned</strong> — vocabulary-list export; an in-app image format converter (renaming and splitting live in preprocessing); a full native mobile app (the responsive web UI works in narrow browser windows); broader integration tests.</div></div>',6)),o("p",null,[e[0]||(e[0]=a("Anything marked ",-1)),d(n,{type:"warning",text:"Planned"}),e[1]||(e[1]=a(" in this site is ",-1)),e[2]||(e[2]=o("strong",null,"not implemented yet",-1)),e[3]||(e[3]=a(". If a page describes behavior that is not in the code, treat this note as authoritative and the feature as unavailable.",-1))]),e[5]||(e[5]=t('<h2 id="the-komayomi-repositories" tabindex="-1">The KomaYomi repositories <a class="header-anchor" href="#the-komayomi-repositories" aria-label="Permalink to &quot;The KomaYomi repositories&quot;">​</a></h2><p>This site documents the desktop edition. The same project ships in three other forms:</p><ul><li><a href="https://github.com/PayayaKamo/KomaYomi" target="_blank" rel="noopener noreferrer">KomaYomi</a> — the full desktop edition (Electron plus a local server) that this documentation covers.</li><li><a href="https://github.com/PayayaKamo/KomaYomi-online" target="_blank" rel="noopener noreferrer">KomaYomi-online</a> — a browser-only build that opens <code>.mnproj</code> projects, reads, annotates and exports without a server.</li><li><a href="https://github.com/PayayaKamo/KomaYomi-mobile" target="_blank" rel="noopener noreferrer">KomaYomi-mobile</a> — a React Native app for Android and iOS; HarmonyOS NEXT is a placeholder for now.</li><li><a href="https://github.com/PayayaKamo/KomaYomi-docs" target="_blank" rel="noopener noreferrer">KomaYomi-docs</a> — the generated build of this site, pushed by CI; edit the docs in the main repository instead.</li></ul><p>Projects use the same page JSON and the same <code>.mnproj</code> format across the editions, so work can move between them.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>New here? Read <a href="/KomaYomi-docs/guide/introduction">Introduction</a>, then <a href="/KomaYomi-docs/guide/installation">Install &amp; Run</a>.</li><li>Want the mental model? Start with <a href="/KomaYomi-docs/concepts">Core Concepts</a>.</li><li>Building on the JSON or writing a plugin? Go to <a href="/KomaYomi-docs/data-format">Data Formats</a> and <a href="/KomaYomi-docs/extending">Layout Templates &amp; Plugins</a>.</li><li>Stuck on a missing page or a broken export? See <a href="/KomaYomi-docs/faq">FAQ &amp; Troubleshooting</a>.</li></ul><div class="tip custom-block"><p class="custom-block-title">Documentation languages</p><p>English is the primary language. A Chinese translation lives under <code>/zh/</code> and a Japanese one under <code>/ja/</code>. Each page states its status separately.</p></div>',7))])}const y=i(m,[["render",p]]);export{b as __pageData,y as default};
